def reviewed_archive_extension_gate(variant, analysis):
    # Review-only assertion: fixed fixtures, not a generic extension policy.
    common = (
        'CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA public;',
        'CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;',
        'CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;',
    )
    expected_by_variant = {
        'SHARED_FIXTURE_SQL_ASCII': common,
        'GENERIC_RENAMED_BOOTSTRAP_UTF8': common + (
            'CREATE EXTENSION IF NOT EXISTS plpgsql WITH SCHEMA pg_catalog;',
        ),
    }
    if type(variant) is not str or variant not in expected_by_variant:
        raise GlobalValidityError('ARCHIVE_EXTENSION_VARIANT_UNKNOWN')
    if type(analysis) is not dict or type(analysis.get('selectedStatements')) is not list:
        raise GlobalValidityError('ARCHIVE_EXTENSION_ANALYSIS_MALFORMED')
    selected = analysis['selectedStatements']
    if any(type(row) is not dict or type(row.get('category')) is not str or
           type(row.get('sql')) is not str for row in selected):
        raise GlobalValidityError('ARCHIVE_EXTENSION_ANALYSIS_MALFORMED')
    rows = [row for row in selected if row['category'] == 'extension']
    observed = [row['sql'] for row in rows]
    expected = expected_by_variant[variant]
    if collections.Counter(observed) != collections.Counter(expected):
        raise GlobalValidityError('ARCHIVE_EXTENSION_ENTRY_SET_MISMATCH')
    return {
        'status': 'PASS', 'variant': variant,
        'expectedCreateStatements': list(expected),
        'actualCreateStatementsInArchiveOrder': list(observed),
        'expectedCount': len(expected), 'actualCount': len(observed),
        'duplicateEntries': False, 'archiveBytesRewritten': False,
    }

